<?php
declare(strict_types=1);require __DIR__.'/config.php';require __DIR__.'/functions.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$action=$_POST['action']??'';if(in_array($action,['approved','rejected'],true)){$pdo->prepare('UPDATE twibbons SET moderation_status=? WHERE id=?')->execute([$action,$id]);$stmt=$pdo->prepare('SELECT owner_id,title FROM twibbons WHERE id=?');$stmt->execute([$id]);if($row=$stmt->fetch())$pdo->prepare('INSERT INTO notifications(user_id,message,url) VALUES(?,?,?)')->execute([$row['owner_id'],'Karya "'.$row['title'].'" '.($action==='approved'?'disetujui.':'ditolak.'),'dashboard']);}elseif($action==='featured')$pdo->prepare('UPDATE twibbons SET is_featured=1-is_featured WHERE id=?')->execute([$id]);elseif($action==='report')$pdo->prepare("UPDATE reports SET status='resolved' WHERE id=?")->execute([$id]);flash('success','Moderasi berhasil diperbarui.');header('Location: moderation');exit;}$pending=$pdo->query("SELECT t.*,u.name author_name FROM twibbons t JOIN users u ON u.id=t.owner_id WHERE t.visibility='public' AND t.moderation_status='pending' ORDER BY t.created_at")->fetchAll();$reports=$pdo->query("SELECT r.*,t.title,u.name reporter FROM reports r JOIN twibbons t ON t.id=r.template_id JOIN users u ON u.id=r.reporter_id WHERE r.status='open' ORDER BY r.created_at DESC")->fetchAll();
?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Moderasi — Semarakin</title><link rel="stylesheet" href="style.css"><link rel="stylesheet" href="teal.css"><link rel="stylesheet" href="auth.css"></head><body><header class="site-header"><div class="container nav"><a class="brand" href="./"><span class="brand-mark">S</span>Semarakin</a></div></header><main class="container"><div class="page-head"><span class="eyebrow">Administrator</span><h1 class="page-title" style="margin-top:12px">Pusat moderasi</h1><p class="subtitle">Jaga kualitas dan keamanan karya publik.</p></div><div class="moderation-grid"><section class="panel"><h2>Menunggu tinjauan</h2><p class="panel-note"><?=count($pending)?> karya perlu diperiksa.</p><?php foreach($pending as $item):?><div class="moderation-item"><img src="uploads/<?=e(basename($item['template_image']))?>"><div><strong><?=e($item['title'])?></strong><small>oleh <?=e($item['author_name'])?></small></div><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$item['id']?>"><button name="action" value="approved" class="btn btn-primary btn-sm">Setujui</button><button name="action" value="rejected" class="btn btn-danger btn-sm">Tolak</button></form></div><?php endforeach?></section><section class="panel"><h2>Laporan pengguna</h2><p class="panel-note"><?=count($reports)?> laporan terbuka.</p><?php foreach($reports as $report):?><div class="report-item"><strong><?=e($report['title'])?></strong><p><?=e($report['reason'])?></p><small>Dilaporkan oleh <?=e($report['reporter'])?></small><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$report['id']?>"><button name="action" value="report" class="btn btn-secondary btn-sm">Tandai selesai</button></form></div><?php endforeach?></section></div></main><footer class="footer">Semarakin · Apins Digital</footer></body></html>
